        self.assertEqual(facts[("NAM", "variable", "NAM_hidden_fuel")], 0)
        before = dict(facts)
        self.apply(block(decision, "cancel_effect"), facts)
        self.apply(block(decision, "remove_effect"), facts)
        self.assertEqual(facts, before)

