    def test_naval_branch_previews_equal_fleet_deltas_and_grants_no_army(self):
        navy = block(parsed("common/dynamic_modifiers/ADISCORD_dynamic_modifiers_NAM.txt"), "NAM_navy_dynamic")
        fields = {entry.value: entry.key for entry in navy if entry.key not in ("icon", "enable")}
        previewed = ("NAM_harbour_service", "NAM_repair_yard", "NAM_escort_school", "NAM_active_squadron",
                     "NAM_naval_construction", "NAM_basin_reconnaissance", "NAM_naval_staff", "NAM_basin_minefields")
        army_unlocks = {"NAM_order_coastal_battalion", "NAM_marine_detachment_order"}
        for name in (*previewed, "NAM_coastal_battalions"):
            reward = block(self.focuses[name], "completion_reward")
            entries = list(walk(reward))
            self.assertFalse(army_unlocks & {e.value for e in entries if e.key == "unlock_decision_tooltip"}, name)
            self.assertFalse({"add_manpower", "army_experience"} & {e.key for e in entries}, name)
            self.assertNotIn("FOCUS_FILTER_ARMY_XP", {e.value for e in block(self.focuses[name], "search_filters")}, name)
            if name not in previewed:
                continue
            ideas = [e.value for e in entries if e.key == "add_idea"]
            self.assertEqual(len(ideas), 1, name)
            deltas = {fields[scalar(e.value, "var")]: Decimal(scalar(e.value, "value"))
                      for e in entries if e.key == "add_to_variable" and scalar(e.value, "var") in fields}
            preview = {e.key: Decimal(e.value) for e in block(self.ideas[ideas[0]], "modifier")}
            self.assertEqual(preview, deltas, name)
        rolls = [e.value for e in block(self.focuses["NAM_reserve_rolls"], "completion_reward")
                 if e.key == "unlock_decision_tooltip"]
        self.assertIn("NAM_order_coastal_battalion", rolls)

    def test_air_and_naval_choices_rejoin_and_remain_optional_to_land_preparation(self):
        pairs = (("NAM_escort_school", "NAM_active_squadron"),
                 ("NAM_air_interceptors", "NAM_air_support"))
        for choices in product(*pairs):
            blocked = {other for pair, chosen in zip(pairs, choices) for other in pair if other != chosen}
            completed = reachable(self.focuses, blocked)
            for final in ("NAM_air_operations", "NAM_coastal_battalions", "NAM_naval_construction", "NAM_basin_minefields", "NAM_island_accounts", "NAM_quartermaster"):
                self.assertIn(final, completed)
            for pair, chosen in zip(pairs, choices):
                self.assertEqual({entry.value for entry in block(self.focuses[chosen], "mutually_exclusive")},
                                 set(pair) - {chosen})
        for name in ("NAM_air_operations", "NAM_naval_construction"):
            requirements = [entry for entry in self.focuses[name] if entry.key == "prerequisite"]
            alternatives = [entry.value for entry in requirements if len(entry.value) == 2]
            self.assertEqual(len(alternatives), 1)
        self.assertEqual(scalar(block(self.focuses["NAM_island_accounts"], "prerequisite"), "focus"), "NAM_harbour_service")
        for choice in pairs[1]:
            days = sum(int(scalar(self.focuses[name], "cost")) * 7 for name in
                       ("NAM_flight_school", "NAM_air_ground_service", choice, "NAM_air_operations"))
            self.assertEqual(days, 49)
            ready = days - int(scalar(self.focuses["NAM_air_operations"], "cost")) * 7
            land_route = self.preparation_route("districts", "export_quays", "mobile_columns", lean=True)
            land_days = sum(int(scalar(self.focuses[name], "cost")) * 7 for name in land_route)
            self.assertLess(land_days + ready, 700)
        plans = read("common/ai_strategy_plans/ADISCORD_NAM_plans.txt")
        self.assertIn("\n\t\tNAM_naval_staff\n", plans)
        self.assertNotIn("\n\t\tNAM_active_squadron\n", plans)
        self.assertNotIn("\n\t\tNAM_air_support\n", plans)

    def test_aircraft_purchases_check_exact_prices_and_deliver_only_to_nam(self):
        for name, focus_id, equipment in (
            ("NAM_air_fighter_order", "NAM_air_interceptors", "ADISCORD_fighter_airframe_2163"),
            ("NAM_air_cas_order", "NAM_air_support", "ADISCORD_cas_airframe_2170"),
        ):
            decision = self.decisions[name]
            self.assertEqual(scalar(decision, "cost"), "0")
            self.assertEqual(scalar(decision, "days_re_enable"), "90")
            self.assertIn(focus_id, [e.value for e in walk(block(decision, "visible")) if e.key == "has_completed_focus"])
            for pp, treasury, fuel, affordable in ((30, 300, 1000, True), (29.99, 300, 1000, False),
                                                   (30, 299.99, 1000, False), (30, 300, 999.99, False)):
                facts = self.independent_facts()
                facts[("NAM", "has_completed_focus", focus_id)] = True
                facts[("NAM", "numeric", "has_political_power")] = pp
                facts[("NAM", "variable", "ADISCORD_economy_treasury")] = treasury
                facts[("NAM", "numeric", "has_fuel")] = fuel
                self.assertEqual(self.matches(block(decision, "custom_cost_trigger"), facts), affordable)
                self.apply(block(decision, "complete_effect"), facts)
                self.assertEqual(facts.get(("NAM", "equipment", equipment), 0), 24 if affordable else 0)
                self.assertEqual(facts[("NAM", "numeric", "has_political_power")], pp - (30 if affordable else 0))
                self.assertEqual(facts[("NAM", "variable", "ADISCORD_economy_treasury")], treasury - (300 if affordable else 0))
                self.assertEqual(facts[("NAM", "numeric", "has_fuel")], fuel - (1000 if affordable else 0))
            for predicate in (("has_capitulated", "no"), ("is_subject", "no"), ("has_country_flag", "NAM_center_vanished")):
                facts = self.independent_facts()
                facts[("NAM", "has_completed_focus", focus_id)] = True
                facts[("NAM", *predicate)] = False
                self.assertFalse(self.matches(block(decision, "available"), facts))
                self.apply(block(decision, "complete_effect"), facts)
                self.assertNotIn(("NAM", "equipment", equipment), facts)

    def test_service_modifiers_use_native_fields_and_registered_service_icons(self):
        from PIL import Image

        vocabulary = json.loads(read("tools/data/adiscord_modifier_fields.json"))
        definitions = parsed("common/dynamic_modifiers/ADISCORD_dynamic_modifiers_NAM.txt")
        sprites = block(parsed("interface/ADISCORD_ideas.gfx"), "spriteTypes")
        for name in ("NAM_garrison_dynamic", "NAM_navy_dynamic", "NAM_air_dynamic"):
            modifier = block(definitions, name)
            icon_name = scalar(modifier, "icon")
            self.assertEqual(icon_name, f"GFX_idea_{name}")
            paths = [scalar(sprite.value, "texturefile") for sprite in sprites
                     if sprite.key == "spriteType" and scalar(sprite.value, "name") == icon_name]
            self.assertEqual(len(paths), 1, icon_name)
            with Image.open(ROOT / paths[0]) as icon:
                self.assertEqual(icon.size, (68, 68))
                self.assertEqual(icon.mode, "RGBA")
            for entry in modifier:
                if entry.key not in ("icon", "enable"):
                    self.assertIn(entry.key, vocabulary["country"], (name, entry.key))

    def test_every_policy_combination_reaches_the_branch_finals(self):
        pairs = (("vertical", "districts"), ("export_quays", "domestic_refining"),
                 ("field_guards", "mobile_columns"), ("supports_oil_compact", "supports_export_houses"),
                 ("court_azhar", "fuel_leverage"), ("island_levy_office", "island_concession"))
        # Course-gated alternatives follow the ladder course chosen in the first pair.
        course = {
            "vertical": {"NAM_district_guarantees", "NAM_weber_channel", "NAM_district_volunteers"},
            "districts": {"NAM_emergency_writ", "NAM_cache_hunters", "NAM_martial_seals"},
        }
        finals = ("NAM_seal_courts", "NAM_civilian_combine", "NAM_quartermaster",
                  "NAM_pillar_arbitration", "NAM_general_staff_plan", "NAM_island_accounts", "NAM_rom_address")
        for choices in product(*pairs):
            blocked = {"NAM_" + other for pair, chosen in zip(pairs, choices) for other in pair if other != chosen}
            completed = reachable(self.focuses, blocked | course[choices[0]])
            for final in finals:
                self.assertIn(final, completed, choices)
            underground_final = "NAM_field_gendarmes" if choices[0] == "vertical" else "NAM_mine_councils"
            other_final = "NAM_mine_councils" if choices[0] == "vertical" else "NAM_field_gendarmes"
            self.assertIn(underground_final, completed, choices)
            self.assertNotIn(other_final, completed, choices)
            for pair, chosen in zip(pairs, choices):
                group = block(self.focuses["NAM_" + chosen], "mutually_exclusive")
                self.assertEqual({e.value for e in group}, {"NAM_" + n for n in pair if n != chosen})
        for state, federal in (("service_state", "federal_charter"), ("federal_charter", "service_state")):
            for peace in (("civil_dividend", "armed_peace"), ("armed_peace", "civil_dividend")):
                completed = reachable(self.postwar, {"NAM_" + federal, "NAM_" + peace[1]})
                self.assertIn("NAM_svetlogorye", completed)
                ending = "NAM_ladder_of_seals" if state == "service_state" else "NAM_common_fuel_market"
                self.assertIn(ending, completed, state)
        for chosen, other in (("revenge", "accommodation"), ("accommodation", "revenge")):
            completed = reachable(self.defeated, {"NAM_defeat_" + other})
            self.assertIn("NAM_defeat_second_chapter", completed, chosen)
        finals = {
            "exile_radical": "NAM_rad_dominion_of_pillars",
            "exile_humanist": "NAM_hum_union_constitution",
        }
        for kind, final in finals.items():
            focuses = self.exile_trees[kind][1]
            pairs = sorted({
                tuple(sorted((name, entry.value)))
                for name, focus in focuses.items()
                for group in (e.value for e in focus if e.key == "mutually_exclusive")
                for entry in group
            })
            self.assertGreaterEqual(len(pairs), 4, kind)
            for side in (0, 1):
                blocked = {pair[1 - side] for pair in pairs}
                self.assertIn(final, reachable(focuses, blocked), (kind, side))

    def test_klyuchevsk_strike_follows_the_field_controller_and_ends_on_liberation(self):
        focuses = self.exile_trees["exile_radical"][1]
        strike = focuses["NAM_exile_klyuchevsk_strike"]
        underground = focuses["NAM_exile_armed_underground"]
        modifier = block(parsed("common/dynamic_modifiers/ADISCORD_dynamic_modifiers_NAM.txt"),
                         "NAM_klyuchevsk_oil_strike")
        self.assertEqual(scalar(modifier, "state_resources_factor"), "-0.50")
        for controller, owner, at_war, allied, subject, won, active in (
            ("AZH", "EFL", False, False, False, False, True),
            ("VAL", "EFL", True, False, False, False, True),
            ("VAL", "EFL", False, False, False, False, False),
            ("VAL", "VAL", False, False, False, False, False),
            ("KDR", "KDR", False, False, False, False, False),
            ("AZH", "EFL", False, True, False, False, False),
            ("AZH", "EFL", False, False, True, False, False),
            ("NAM", "EFL", False, False, False, False, False),
            ("EFL", "EFL", False, False, False, True, False),
        ):
            with self.subTest(controller=controller, owner=owner, won=won, allied=allied, subject=subject):
                facts = self.facts()
                facts.update({("67", "controller"): controller, ("67", "owner"): owner,
                              ("67", "is_controlled_by", "NAM"): controller == "NAM",
                              (controller, "owns_state", "PREV"): controller == owner,
                              (controller, "exists", "yes"): True, (controller, "has_capitulated", "no"): True,
                              (controller, "is_subject", "no"): not subject,
                              (controller, "is_subject_of", "NAM"): subject,
                              (controller, "is_in_faction_with", "NAM"): allied,
                              (controller, "has_war_with", "NAM"): at_war,
                              ("67", "has_global_flag", "NAM_war_of_return_won"): won})
                self.assertEqual(self.matches(block(strike, "available"), facts), active)
                self.assertEqual(self.matches(block(modifier, "enable"), facts, "67"), active)
                self.assertEqual(self.matches(block(modifier, "remove_trigger"), facts, "67"), not active)
                for focus, effect, value in ((strike, "add_fuel", "-30000"),
                                             (underground, "add_stability", "-0.03")):
                    actions = [entry for scope, entry in selected_effects(
                        self.expand(block(focus, "completion_reward")), facts, "NAM") if scope == "67"]
                    self.assertFalse(any(entry.key == "owner" for entry in actions))
                    effects = [scalar(entry.value, effect) for entry in actions if entry.key == "controller"]
                    self.assertEqual(effects, [value] if active else [])
                    if focus is strike:
                        timers = [scalar(entry.value, "days") for entry in actions if entry.key == "add_dynamic_modifier"]
                        self.assertEqual(timers, ["180"] if active else [])
                if active and not at_war:
                    facts[(controller, "has_global_flag", "NAM_war_of_return_started")] = True
                    self.assertFalse(self.matches(block(modifier, "enable"), facts, "67"))
                    facts[(controller, "has_war_with", "NAM")] = True
                    self.assertTrue(self.matches(block(modifier, "enable"), facts, "67"))

    def test_penal_mines_pay_only_for_controlled_sites_and_never_block_the_capital(self):
        focuses = self.exile_trees["exile_radical"][1]
        mines = focuses["NAM_rad_penal_mines"]
        for east, north in product(range(4), repeat=2):
            facts = self.independent_facts()
            expected = []
            for state, status, resource in (("227", east, "tungsten"), ("229", north, "chromium")):
                facts[(state, "is_owned_by", "NAM")] = bool(status & 1)
                facts[(state, "is_controlled_by", "NAM")] = bool(status & 2)
                if status == 3:
                    expected.append((state, resource, "2"))
            with self.subTest(east=east, north=north):
                self.assertEqual(self.matches(block(mines, "available"), facts), bool(expected))
                self.assertEqual(self.matches(block(mines, "bypass"), facts), not expected)
                reward = [e for _, e in selected_effects(self.expand(block(mines, "completion_reward")), facts, "NAM")]
                delivered = [(scalar(e.value, "state"), scalar(e.value, "type"), scalar(e.value, "amount"))
                             for e in reward if e.key == "add_resource"]
                self.assertEqual(delivered, expected)
                self.assertEqual(any(e.key == "add_stability" for e in reward), bool(expected))
                self.assertEqual(any(e.key == "NAM_groups_refresh" for e in reward), bool(expected))
                # Completing or bypassing the mines leaves the same route open.
                completed = {"NAM_rad_military_roads", "NAM_rad_penal_mines", "NAM_rad_island_airfields"}
                requirements = [e.value for e in focuses["NAM_rad_fortress_capital"] if e.key == "prerequisite"]
                self.assertTrue(all(any(e.value in completed for e in group) for group in requirements))

    def test_island_focus_diagram_and_duration(self):
        focuses = self.exile_trees["exile_corporate"][1]
        self.assertEqual(len(focuses), 116)
        positions = {}
        edges = []
        pairs = set()
        for name, focus in focuses.items():
            self.assertTrue(0 < float(scalar(focus, "cost")) <= 3, name)
            positions[name] = (int(scalar(focus, "x")), int(scalar(focus, "y")))
            for field in focus:
                if field.key == "prerequisite":
                    edges.extend((parent.value, name) for parent in field.value)
                elif field.key == "mutually_exclusive":
                    pairs.update(tuple(sorted((name, other.value))) for other in field.value)
        self.assertEqual(len(pairs), 12)
        root = "NAM_board_beacon_out"
        final = "NAM_board_operation_poseidon"
        self.assertEqual(set(focuses) - {child for _, child in edges}, {root})
        # The invasion branch ends on Poseidon; the Sharden landing is its optional side leaf.
        self.assertEqual(set(focuses) - {parent for parent, _ in edges}, {final, "NAM_board_sharden_operation"})
        self.assertEqual(positions[root][0], positions[final][0])
        self.assertEqual(positions[root][0], positions["NAM_board_partition_night"][0])
        self.assertLess(positions["NAM_board_escheated_throne"][0], positions["NAM_board_posthumous_signature"][0])
        for parent, child in edges:
            self.assertLess(positions[parent][1], positions[child][1], (parent, child))
        reparented = (("NAM_board_dead_mans_veto", "NAM_board_inheritance_without_empire"),
                      ("NAM_board_founders_of_unrest", "NAM_board_elected_in_absentia"))
        crossings = [(reparented[0], ("NAM_board_escheated_throne", "NAM_board_posthumous_signature"), (12, 6)),
                     (reparented[1], ("NAM_board_last_debtor", "NAM_board_treaty_two_judases"), (24, 6))]
        for parent, child in reparented:
            self.assertEqual([source for source, target in edges if target == child], [parent])
        for kind, conflicts in corporate_focus_wiring(positions, edges, sorted(pairs)).items():
            self.assertCountEqual(conflicts, crossings if kind == "crossings" else [], kind)

    def test_partition_freezes_the_top_two_vote_recipients(self):
        focus = self.exile_trees["exile_corporate"][1]["NAM_board_partition_night"]
        self.assertEqual(scalar(block(focus, "available"), "NAM_board_majority_held"), "yes")
        facts = self.board_facts()
        self.apply(self.effects["NAM_board_initialize"], facts)
        for lot in ("rail", "yards", "depots"):
            facts[("NAM", "variable", "NAM_board_lot_" + lot)] = 6
        self.apply(self.effects["NAM_board_recount"], facts)
        votes = {company: facts[("NAM", "variable", f"NAM_board_votes_{company}")] for company in range(1, 7)}
        order = sorted(votes, key=lambda company: (-votes[company], company))
        support = ("NAM", "array", "NAM_board_support")
        before = tuple(facts[support])
        self.apply(block(focus, "completion_reward"), facts)
        for index, company in enumerate(order):
            self.assertEqual(facts[support][company], max(0, min(100, before[company] + (10 if index < 2 else -5))))
        for lot in ("rail", "yards", "depots"):
            facts[("NAM", "variable", "NAM_board_lot_" + lot)] = 2
        self.apply(self.effects["NAM_board_recount"], facts)
        self.assertNotEqual(facts[("NAM", "variable", "NAM_board_rank_1")], order[0])
        turn = ("NAM", "variable", "NAM_corp_next_owner")
        facts[turn] = 4
        for tag, expected in zip(("EFL", "AZH"), order):
            for _ in range(2):
                self.apply(self.effects["NAM_corp_assign_district"], facts, tag)
                self.assertEqual(facts[(tag, "variable", "NAM_corp_district_owner")], expected)
                self.assertEqual(facts[turn], 4)

    def test_upper_reward_previews_equal_the_applied_deltas(self):
        components = {"pp": "political_power_gain", "stab": "stability_factor", "org": "army_org_factor",
                      "output": "industrial_capacity_factory", "construction": "production_speed_buildings_factor",
                      "goods": "consumer_goods_factor", "research": "research_speed_factor"}
        seen = set()
        for name, focus in self.exile_trees["exile_corporate"][1].items():
            reward = next((field.value for field in focus if field.key == "completion_reward"), [])
            applied, preview = Counter(), Counter()
            for field in reward:
                if field.key == "effect_tooltip":
                    for idea in (entry.value for entry in field.value if entry.key == "add_ideas"):
                        seen.add(idea)
                        for entry in block(self.ideas[idea], "modifier"):
                            preview[entry.key] += Decimal(entry.value)
                elif field.key == "hidden_effect":
                    for row in walk(field.value):
                        if row.key == "add_to_variable":
                            variable = scalar(row.value, "var")
                            if variable.startswith("NAM_board_focus_"):
                                applied[components[variable.removeprefix("NAM_board_focus_")]] += Decimal(scalar(row.value, "value"))
            self.assertEqual(preview, applied, name)
        self.assertEqual(len(seen), 12)

    def test_upper_programmes_unlock_in_the_council_without_mainland_focuses(self):
        council = block(parsed(f"common/decisions/{BASE}_decisions.txt"), "NAM_free_zones")
        category = block(parsed(f"common/decisions/categories/{BASE}_categories.txt"), "NAM_free_zones")
        gates = (("private_gospel", "NAM_corp_sell_steel"), ("land_foreclosure", "NAM_corp_labour_contract"),
                 ("island_fleet_shares", "NAM_island_convoy_service"), ("boundary_notches", "NAM_island_public_works"),
                 ("concession_courts", "NAM_island_concession_231"), ("last_voyage_rifles", "NAM_order_marines"),
                 ("corporate_mass_housing", "NAM_board_commission_housing"), ("incumbents_credit", "NAM_board_underwrite_payroll"),
                 ("eflor_debt_purchase", "NAM_board_redeem_mortgages"))
        for short, programme in gates:
            name = "NAM_board_" + short
            facts = self.island_facts()
            facts.update(self.marine_order_facts())
            for key in list(facts):
                if len(key) == 3 and key[1] == "has_completed_focus":
                    facts[key] = False
            facts[("VAL", "exists", "yes")] = True
            facts[("VAL", "has_capitulated", "no")] = True
            facts[("NAM", "is_subject", "no")] = True
            focus = self.exile_trees["exile_corporate"][1][name]
            self.assertIn(programme, [row.value for row in block(focus, "completion_reward") if row.key == "unlock_decision_tooltip"])
            decision = self.bind_field(block(council, programme), "VAL" if short == "concession_courts" else "230")
            self.assertTrue(self.matches(block(category, "visible"), facts), programme)
            self.assertFalse(self.matches(block(decision, "visible"), facts), programme)
            facts[("NAM", "has_completed_focus", name)] = True
            self.assertTrue(self.matches(block(decision, "visible"), facts), programme)
            if short in {"island_fleet_shares", "boundary_notches", "concession_courts", "last_voyage_rifles"}:
                self.assertTrue(self.matches(block(decision, "available"), facts), programme)

    def test_partition_requires_every_compatible_branch_and_only_spared_leaders_are_wip(self):
        # The partition gate is the last upper focus (rows 0-12); the invasion branch
        # below it opens only afterwards and has its own completeness tests.
        focuses = {name: focus for name, focus in self.exile_trees["exile_corporate"][1].items()
                   if int(scalar(focus, "y")) <= 12}
        self.assertEqual(len(focuses), 70)
        final = "NAM_board_partition_night"
        start = "NAM_board_beacon_out"
        wip = {"NAM_board_escheated_throne", "NAM_board_treaty_two_judases"}
        requirements = {}
        conditions = {}
        pairs = set()
        seen_wip = set()
        for name, focus in focuses.items():
            requirements[name] = []
            conditions[name] = []
            for field in focus:
                if field.key == "prerequisite":
                    requirements[name].append({parent.value for parent in field.value})
                elif field.key == "mutually_exclusive":
                    pairs.update(tuple(sorted((name, other.value))) for other in field.value)
                elif field.key == "available":
                    conditions[name] = field.value
                    if any(e.key == "always" and e.value == "no" for e in walk(field.value)):
                        seen_wip.add(name)
                        reason = block(field.value, "custom_trigger_tooltip")
                        self.assertEqual(scalar(reason, "tooltip"), "NAM_island_wip_tt")
                        self.assertEqual(scalar(reason, "always"), "no")
                        reward = block(focus, "completion_reward")
                        self.assertEqual(scalar(reward, "custom_effect_tooltip"), "NAM_island_wip_tt")
        self.assertEqual(seen_wip, wip)
        ordered = sorted(focuses, key=lambda name: int(scalar(focuses[name], "y")))
        children = {name: {child for child, groups in requirements.items() if any(name in g for g in groups)}
                    for name in focuses}

        def leading_to_final(blocked):
            # The parent of a rejected exclusive side may lead nowhere else; it stays
            # selectable but cannot be required. Children always sit on a lower row.
            live = {final}
            for name in reversed(ordered):
                if name not in blocked and children[name] & live:
                    live.add(name)
            return live

        def play(blocked, enable_spared):
            done = set()
            facts = self.mature_board_gate_facts()
            for name in ordered:
                if name in blocked or any(not (g & done) for g in requirements[name]):
                    continue
                available = conditions[name]
                if enable_spared and name in wip:
                    available = [entry for entry in available if entry.key != "custom_trigger_tooltip"]
                if matches_conditions(available, facts, "NAM"):
                    done.add(name)
                    facts[("NAM", "has_completed_focus", name)] = True
            return done

        for choices in product(*sorted(pairs)):
            blocked = set(choices)
            for enable_spared in (False, True):
                completed = play(blocked, enable_spared)
                survivors = len(wip - blocked)
                self.assertEqual(final in completed, survivors == 0 or (enable_spared and survivors == 1),
                                 (choices, enable_spared))
                if final in completed:
                    optional = completed - leading_to_final(blocked)
                    if enable_spared and "NAM_board_treaty_two_judases" in completed:
                        optional.update({"NAM_board_elected_in_absentia", "NAM_board_widows_share",
                                         "NAM_board_proxy_parliament", "NAM_board_ministries_in_concession"})
                    if enable_spared and "NAM_board_escheated_throne" in completed:
                        optional.update({"NAM_board_inheritance_without_empire", "NAM_board_uncrested_buyers",
                                         "NAM_board_silence_after_settlement", "NAM_board_escheated_land_auction"})
                    for name in completed - {start, final}:
                        self.assertEqual(final in play(blocked | {name}, enable_spared), name in optional, name)

    @staticmethod
    def mature_board_gate_facts():
        # A council a year old that still governs: open, independent, not ended.
        return {("NAM", "has_country_flag", "NAM_board_opened"): True,
                ("NAM", "flag_days", "NAM_board_opened"): 365,
                ("NAM", "NAM_board_majority_held", "yes"): True,
                ("NAM", "NAM_board_operable", "yes"): True}

    def test_corporate_ai_completes_every_compatible_focus_before_poseidon(self):
        plan = block(parsed("common/ai_strategy_plans/ADISCORD_NAM_plans.txt"), "NAM_exile_corporate_plan")
        queue = [entry.value for entry in block(plan, "ai_national_focuses")]
        tree = self.exile_trees["exile_corporate"][1]
        facts = self.board_facts()
        facts.update(self.mature_board_gate_facts())
        facts[("NAM", "NAM_board_operable", "yes")] = self.matches(self.triggers["NAM_board_operable"], facts)
        facts.update({("NAM", "has_focus_tree", "NAM_exile_corporate_focus"): True,
                      ("NAM", "is_ai", "yes"): True})
        # A prepared expedition: Poseidon's own readiness, force, marine and convoy gates.
        facts.update({("NAM", "variable", "NAM_revenge_readiness"): 70,
                      ("NAM", "numeric", "num_divisions"): 8,
                      ("NAM", "NAM_board_poseidon_marines_ready", "yes"): True,
                      ("NAM", "equipment", "convoy_1"): 20,
                      ("NAM", "NAM_board_invasion_backers_ready", "yes"): True,
                      ("NAM", "NAM_war_of_return_can_start", "yes"): True,
                      ("ULV", "exists", "yes"): True,
                      ("ULV", "is_subject", "no"): True})
        self.assertTrue(self.matches(block(plan, "enable"), facts))
        self.assertFalse(self.matches(block(plan, "abort"), facts))
        completed = set()

        def comparisons(entries):
            # Scripted predicates stay fact-bound; only the short check_variable form is rewritten.
            return [replace(entry, value=self.expand([entry])[0].value) if entry.key == "check_variable"
                    else replace(entry, value=comparisons(entry.value)) if isinstance(entry.value, list)
                    else entry for entry in entries]

        def selectable(name):
            for entry in tree[name]:
                if entry.key == "prerequisite" and completed.isdisjoint(row.value for row in entry.value):
                    return False
                if entry.key == "mutually_exclusive" and any(row.value in completed for row in entry.value):
                    return False
                if entry.key == "available" and not matches_conditions(comparisons(entry.value), facts, "NAM"):
                    return False
            return True

        self.assertEqual(queue[0], "NAM_board_beacon_out")
        self.assertEqual(queue[-1], "NAM_board_operation_poseidon")
        self.assertLess(queue.index("NAM_board_partition_night"), queue.index("NAM_board_invasion_prospectus"))
        self.assertTrue({"NAM_board_posthumous_signature", "NAM_board_last_debtor"}.issubset(queue))
        self.assertTrue({"NAM_board_treaty_two_judases", "NAM_board_escheated_throne"}.isdisjoint(queue))
        # The AI lands only on Ulven; Luren and Sharden stay outside its plan.
        self.assertIn("NAM_board_ulven_operation", queue)
        self.assertTrue({"NAM_board_luren_operation", "NAM_board_sharden_operation"}.isdisjoint(queue))
        for name in queue:
            self.assertNotIn(name, completed)
            self.assertIn(name, tree)
            self.assertTrue(selectable(name), name)
            facts[("NAM", "has_completed_focus", name)] = True
            completed.add(name)
        # Only the optional island landings the AI skips remain selectable.
        facts.update({("LUR", "exists", "yes"): True, ("LUR", "is_subject", "no"): True})
        self.assertEqual({name for name in tree.keys() - completed if selectable(name)}, {"NAM_board_luren_operation"})

    def test_society_law_requires_the_boards_and_their_focus(self):
        # The 99 to 1 law is a council law: only its focus enacts it, and it cannot be left.
        name = "NAM_board_society_99_1"
        token = "NAM_welfare_society_99_1"
        groups = block(parsed(f"common/ideas/{BASE}_ideas.txt"), "ideas")
        law = block(block(groups, "ADISCORD_welfare_laws"), token)
        reward = block(self.exile_trees["exile_corporate"][1][name], "completion_reward")
        self.assertNotIn("add_ideas", [entry.key for entry in reward])
        self.assertEqual(scalar(reward, "NAM_board_enact_society_99_1"), "yes")
        self.assertEqual(scalar(law, "cost"), "0")
        for tag in ("NAM", "VAL"):
            for corporate in (False, True):
                for completed in (False, True):
                    for held in (False, True):
                        facts = self.board_facts()
                        facts[(tag, "has_country_flag", "NAM_corp_takeover")] = corporate
                        facts[(tag, "has_completed_focus", name)] = completed
                        facts[(tag, "has_idea", token)] = held
                        with self.subTest(tag=tag, corporate=corporate, completed=completed, held=held):
                            self.assertEqual(self.matches(block(law, "allowed"), facts, tag), tag == "NAM")
                            self.assertEqual(self.matches(block(law, "visible"), facts, tag), held)
                            self.assertFalse(self.matches(block(law, "available"), facts, tag))
                            self.assertFalse(self.matches(block(law, "allowed_to_remove"), facts, tag))

    def test_corporate_wiring_distinguishes_a_shared_fork_from_an_unrelated_contact(self):
        diamond = {"p": (2, 0), "l": (0, 1), "r": (4, 1), "q": (2, 2)}
        fork_join = [("p", "l"), ("p", "r"), ("l", "q"), ("r", "q")]
        self.assertFalse(any(corporate_focus_wiring(diamond, fork_join, [("l", "r")]).values()))
        staggered = {"a": (0, 0), "b": (2, 0), "c": (2, 1), "d": (4, 1)}
        contact = corporate_focus_wiring(staggered, [("a", "c"), ("b", "d")], [])
        self.assertEqual(contact["crossings"], [(("a", "c"), ("b", "d"), (2, 1))])
        tall = {"p": (0, 0), "l": (0, 1), "r": (4, 1), "q": (2, 2)}
        crossed = corporate_focus_wiring(tall, [("p", "q")], [("l", "r")])
        self.assertEqual(crossed["crossings"], [(("p", "q"), ("l", "r"), (2, 2))])
        tall["middle"] = (2, 1)
        self.assertIn(("p", "q", "middle"), corporate_focus_wiring(tall, [("p", "q")], [])["card_hits"])

    @staticmethod
    def board_stocks(facts):
        accounts = (("numeric", "has_fuel"), ("numeric", "has_manpower"),
                    ("variable", "NAM_corp_capital"), ("variable", "ADISCORD_economy_treasury"))
        balance = {key: facts.get(("NAM", *key), 0) for key in accounts}
        balance.update({key[1:]: value for key, value in facts.items() if key[:2] == ("NAM", "equipment")})
        return balance

    def board_facts(self):
        facts = self.facts(fuel=0)
        facts[("NAM", "has_country_flag", "NAM_corp_takeover")] = True
        facts[("NAM", "variable", "NAM_revenge_readiness")] = 0
        facts[("NAM", "is_subject", "no")] = True
        facts[("global", "variable", "num_days")] = 2000
        facts[("fixture", "board_callbacks")] = ()
        return facts

    def test_corporate_spirits_settle_once_and_follow_readiness_assets_and_free_zones(self):
        trio = {"NAM_board_army", "NAM_board_politics", "NAM_board_industrial_policy"}
        install = self.effects["NAM_board_install_spirits"]
        self.assertEqual({scalar(e.value, "modifier") for e in walk(install) if e.key == "add_dynamic_modifier"}, trio)
        for debug in (False, True):
            facts = self.board_facts()
            facts[("NAM", "has_country_flag", "NAM_debug_corporate_start")] = debug
            facts[("NAM", "has_country_flag", "NAM_groups_initialized")] = True
            calls = [e.key for _, e in selected_effects(self.expand(self.effects["NAM_corp_takeover"]), facts, "NAM")]
            self.assertEqual(calls.count("NAM_board_install_spirits"), int(not debug))
            if debug:
                reset = [e.key for e in self.effects["NAM_debug_prepare_corporate_start"]]
                self.assertLess(reset.index("NAM_board_recount"), reset.index("NAM_board_install_spirits"))
                self.assertLess(reset.index("NAM_board_install_spirits"), reset.index("set_stability"))
            for row in walk(install):
                if row.key == "remove_dynamic_modifier":
                    facts[("NAM", "has_dynamic_modifier", scalar(row.value, "modifier"))] = True
            self.apply(self.effects["NAM_board_initialize"], facts)
            for readiness, zones in ((0, 0), (50, 2), (100, 1)):
                facts[("NAM", "variable", "NAM_revenge_readiness")] = readiness
                facts[("NAM", "variable", "NAM_free_zones_active")] = zones
                if readiness == 0:
                    self.apply(install, facts)
                self.apply(self.effects["NAM_revenge_readiness_clamp"], facts)
                self.apply(self.effects["NAM_corp_refresh"], facts)
                self.apply(self.effects["NAM_board_recount"], facts)
                self.apply(self.effects["NAM_groups_refresh"], facts)
                self.assertAlmostEqual(facts[("NAM", "variable", "NAM_board_expedition_planning")], (readiness - 100) / 1000)
                self.assertAlmostEqual(facts[("NAM", "variable", "NAM_corp_mod_tax")], -0.03 * zones)
                # Both efficiency lines (Ferrant -3, Smenkom -2) are closed at the takeover.
                self.assertAlmostEqual(facts[("NAM", "variable", "NAM_board_mod_growth")], -0.05)
                self.assertAlmostEqual(facts[("NAM", "variable", "NAM_corp_mod_research")], -0.10)
                self.assertEqual({key[2] for key in facts if len(key) == 3 and key[:2] == ("NAM", "has_dynamic_modifier") and facts[key]}, trio)
            step = [row for row in walk(block(self.exile_trees["exile_corporate"][1]["NAM_board_foundry_mark"], "completion_reward"))
                    if row.key == "add_to_variable" and scalar(row.value, "var") == "NAM_board_focus_research"]
            self.assertEqual(len(step), 1)
            self.apply(step, facts)
            self.apply(self.effects["NAM_board_recount"], facts)
            self.assertAlmostEqual(facts[("NAM", "variable", "NAM_corp_mod_research")], 0)
        modifiers = parsed("common/dynamic_modifiers/ADISCORD_dynamic_modifiers_NAM.txt")
        sprites = {scalar(e.value, "name").strip('"'): scalar(e.value, "texturefile").strip('"')
                   for e in block(parsed("interface/ADISCORD_ideas.gfx"), "spriteTypes") if e.key == "spriteType"}
        textures = set()
        for spirit in trio:
            artwork = ROOT / sprites[scalar(block(modifiers, spirit), "icon")]
            header = artwork.read_bytes()[:24]
            self.assertEqual(header[:8], bytes.fromhex("89504e470d0a1a0a"))
            self.assertEqual(int.from_bytes(header[16:20], "big"), 68)
            self.assertEqual(int.from_bytes(header[20:24], "big"), 68)
            textures.add(artwork.read_bytes())
        self.assertEqual(len(textures), 3)

    def test_corporate_takeover_exposes_only_the_island_categories(self):
        facts = self.board_facts()
        flag = ("NAM", "has_country_flag", "NAM_debug_corporate_start")
        facts.update({
            flag: True,
            ("NAM", "is_debug", "yes"): True,
            ("NAM", "original_tag", "NAM"): True,
            ("NAM", "has_country_flag", "SHL_metal_client"): True,
            ("NAM", "has_country_flag", "NAM_groups_initialized"): True,
            ("NAM", "has_global_flag", "ADISCORD_nam_resource_war_island_exile"): True,
        })
        directory = ROOT / "common/decisions/categories"
        allowed = {}
        for path in directory.glob("*.txt"):
            for category in parsed(path):
                eligibility = next((e.value for e in category.value if e.key == "allowed"), [])
                if self.matches(eligibility, facts):
                    allowed[category.key] = next((e.value for e in category.value if e.key == "visible"), [])
        # Only the categories' own visible triggers are evaluated here; the engine
        # still hides the development category until one of its programmes is visible.
        expected = {"NAM_two_judases", "NAM_free_zones", "NAM_public_campaigns", "NAM_directory_development"}
        for debug in (False, True):
            facts[flag] = debug
            self.assertEqual({key for key, visible in allowed.items() if self.matches(visible, facts)}, expected)
        for category, value in (
            ("NAM_southern_lands", "NAM_southern_lands_open"),
            ("NAM_consolidation", "NAM_consolidation_started"),
        ):
            with self.subTest(category=category):
                advanced = {**facts, ("NAM", "has_country_flag", value): True}
                self.assertTrue(self.matches(allowed[category], advanced))
        board = block(parsed(f"common/decisions/{BASE}_decisions.txt"), "NAM_free_zones")
        self.assertFalse({row.key for row in board} &
                        {"NAM_board_tender_rail", "NAM_board_tender_yards", "NAM_board_tender_depots"})
        self.assertTrue({"NAM_board_bid_" + lot for lot in ("rail", "yards", "depots")} <= {row.key for row in board})
        # 52 council decisions, the proxy purchase, the settlers' militia, the relief
        # fund and the one retender decision.
        self.assertEqual(len(board), 56)
        self.assertFalse({row.key for row in board if row.key.startswith("NAM_dir_campaign_")})
        public_campaigns = block(parsed(f"common/decisions/{BASE}_decisions.txt"), "NAM_public_campaigns")
        # Eleven pre-war campaigns and the eight Directory campaigns.
        self.assertEqual(len(public_campaigns), 19)
        self.assertEqual({row.key for row in public_campaigns if row.key.startswith("NAM_dir_campaign_")},
                         {"NAM_dir_campaign_" + name for name in
                          ("newsreel", "dividend", "pays_on_time", "agitators", "mutineers", "return", "lottery", "gazette")})

    def test_evacuation_closes_the_basin_panel_and_its_incident_clock(self):
        categories = parsed(f"common/decisions/categories/{BASE}_categories.txt")
        category = block(block(categories, "NAM_national_programmes"), "visible")
        gui = block(parsed("common/scripted_guis/ADISCORD_NAM_scripted_gui.txt"), "scripted_gui")
        panel = block(block(gui, "ADISCORD_NAM_basin_panel"), "visible")
        countdown = ("NAM", "has_active_mission", "NAM_incident_countdown")
        response = ("NAM", "has_active_mission", "NAM_incident_response")
        case = ("NAM", "has_country_flag", "NAM_crisis_open")
        exile = ("NAM", "has_global_flag", "ADISCORD_nam_resource_war_island_exile")
        settlement = next(scope.value for scope in self.effects["NAM_rw_settle_island_exile"]
                          if scope.key == "NAM" and any(entry.key == "remove_mission" for entry in walk(scope.value)))
        self.assertIn("NAM_rw_settle_island_exile",
                      {entry.key for entry in walk(self.effects["ADISCORD_nam_resource_war_resolve_coalition_victory"])})
        for active in (countdown, response):
            facts = self.economy_facts()
            facts.update({active: True, case: active == response,
                          ("NAM", "has_country_flag", "NAM_groups_initialized"): True})
            self.assertTrue(self.matches(category, facts))
            self.assertTrue(self.matches(panel, facts))
            facts[exile] = True
            self.apply(settlement, facts)
            self.assertFalse(facts.get(countdown))
            self.assertFalse(facts.get(response))
            self.assertFalse(facts[case])
            self.assertFalse(self.matches(category, facts))
            self.assertFalse(self.matches(panel, facts))
            self.apply(self.effects["NAM_crisis_draw"], facts)
            self.apply(block(self.missions["NAM_incident_countdown"], "timeout_effect"), facts)
            self.assertFalse(facts.get(countdown))
            self.assertFalse(facts.get(response))
            for number in range(1, 10):
                trigger = block(self.events[f"ADISCORD_nam_crisis.{number}"], "trigger")
                self.assertFalse(self.matches(trigger, facts))
                self.assertTrue(self.matches(trigger, {**facts, exile: False}))

    def assert_board_industry(self, facts, factors, charters=(2,) * 6):
        # Charter level 1 opens line A, level 2 both lines; a closed line applies
        # minus its factor whatever the stance, while the potential stays live.
        total = Counter()
        for company, (profile, factor, charter) in enumerate(zip(BOARD_PROFILES, factors, charters), 1):
            for level, rate, (field, points) in zip((1, 2), ("a", "b"), profile):
                potential = factor * points
                self.assertAlmostEqual(facts[("NAM", "variable", f"NAM_board_potential_{rate}_{company}")], potential)
                contribution = potential if charter >= level else -points
                self.assertAlmostEqual(facts[("NAM", "variable", f"NAM_board_rate_{rate}_{company}")], contribution)
                total[field] += contribution
        for field, points in total.items():
            self.assertAlmostEqual(facts[("NAM", "variable", "NAM_board_mod_" + field)], points / 100, msg=field)

    def test_olshansky_fills_all_seven_portfolios_with_three_board_nominees(self):
        slots = [e.value for e in walk(block(parsed("common/idea_tags/00_idea.txt"), "idea_categories"))
                 if e.key == "slot" and e.value.startswith("political_advisor_")]
        cabinet = self.effects["NAM_board_appoint_cabinet"]
        self.assertFalse(any(e.key.endswith("coalition_party") for e in walk(cabinet)))
        expected = ("NAM_board_premier_kornev", "NAM_board_defense_selivanov", "NAM_board_bank_nominee",
                    "NAM_board_health_veresov", "NAM_board_labor_nominee", "NAM_board_intelligence_bulatov",
                    "NAM_board_min_navis_foreign")
        appointments = [e.value for e in cabinet if e.key == "add_ideas"]
        self.assertEqual(appointments, list(expected))
        defined = {}
        for filename in ("ADISCORD_ministers_all_countries.txt", f"{BASE}_ideas.txt"):
            for slot in block(parsed("common/ideas/" + filename), "ideas"):
                if slot.key in slots:
                    defined.update({idea.key: slot.key for idea in slot.value})
        self.assertEqual([defined[minister] for minister in appointments], slots)
        self.assertEqual(len(slots), 7)
        facts = self.board_facts()
        for minister in defined:
            if minister.startswith("minister_NAM_"):
                facts[("NAM", "has_idea", minister)] = True
        for entry in cabinet:
            if entry.key in ("remove_ideas", "add_ideas"):
                facts[("NAM", "has_idea", entry.value)] = entry.key == "add_ideas"
        occupied = {minister for minister in defined if facts.get(("NAM", "has_idea", minister))}
        self.assertEqual(occupied, set(appointments))
        self.apply(self.effects["NAM_board_initialize"], facts)
        self.apply(self.effects["NAM_board_recount"], facts)
        self.assertEqual([facts[("NAM", "variable", f"NAM_board_votes_{i}")] for i in range(1, 7)],
                         [4, 2, 5, 2, 5, 3])
        self.assertEqual(facts[("NAM", "variable", "NAM_board_rank_1")], 3)
        ordinary = self.effects["NAM_corp_takeover"]
        leader, = (scalar(e.value, "character") for e in walk(ordinary) if e.key == "add_country_leader_role"
                   and any(a.key == "promote_leader" and a.value == "yes" for a in e.value))
        self.assertEqual(leader, "NAM_Mark_Olshansky")
        premier = block(block(block(parsed(f"common/ideas/{BASE}_ideas.txt"), "ideas"), slots[0]), expected[0])
        self.assertNotEqual(scalar(premier, "picture"), leader)
        for language in ("russian", "english"):
            loc = read(f"localisation/{language}/{BASE}_l_{language}.yml")
            def display_name(key):
                return re.search(rf'^ {key}:\d* "([^"]+)"', loc, re.M).group(1)
            self.assertNotEqual(display_name(leader), display_name(expected[0]))
        guard, = (e.value for e in ordinary if e.key == "if" and
                  any(row.key == "NAM_board_appoint_cabinet" for row in e.value))
        self.assertTrue(self.matches(block(guard, "limit"), facts))
        facts[("NAM", "has_country_flag", "NAM_debug_corporate_start")] = True
        self.assertTrue(self.matches(block(guard, "limit"), facts))
        facts[("NAM", "has_country_flag", "NAM_board_opened")] = True
        self.assertFalse(self.matches(block(guard, "limit"), facts))
        debug = [e.key for e in self.effects["NAM_debug_prepare_corporate_start"]]
        self.assertLess(debug.index("ADISCORD_debug_clear_country_ideas"), debug.index("NAM_board_appoint_cabinet"))
        self.assertLess(debug.index("NAM_board_appoint_cabinet"), debug.index("NAM_board_recount"))

    def test_board_fills_empty_designer_slots_and_keeps_existing_appointments(self):
        slots = ("ADISCORD_electronics_designer", "ADISCORD_logistics_designer")
        choices = {slot: {} for slot in slots}
        for path in (ROOT / "common/ideas").glob("*.txt"):
            for group in block(parsed(path), "ideas"):
                if group.key in choices:
                    choices[group.key].update({e.key: e.value for e in group.value if isinstance(e.value, list)})
        defaults = {}
