            self.apply(block(order, "remove_effect"), facts)
            self.assertEqual((facts[money], facts[pp]), cost)
            self.assertEqual(facts[claim], 1)
            self.assertFalse(facts.get(("NAM", "has_idea", "NAM_pw_" + programme + "_idea")))



