    def test_judas_same_day_stand_orders_by_acceptance(self):
        decisions = block(parsed(f"common/decisions/{BASE}_decisions.txt"), "NAM_two_judases")
        cases = (("weber", 5, 2, "smenkom", "buy_notes", "founders_of_unrest", 450),
                 ("karamyshev", 2, 3, "ferrant", "register_patents", "dead_mans_veto", 451))
        for camp, company, motion, owner, operation, focus, event in cases:
            decision = block(decisions, "NAM_judas_" + operation)
            force_answer = [entry.value for entry in self.events[f"{BASE}.{event}"] if entry.key == "option"][2]
            for force in (False, True):
                for after in (False, True):
                    with self.subTest(camp=camp, force=force, after=after):
                        facts = self.judas_facts()
                        if force:
                            pending = "NAM_judas_" + camp + "_pending"
                            facts[("NAM", "has_variable", pending)] = True
                            facts[("NAM", "variable", pending)] = 1
                            action = block(force_answer, "hidden_effect")
                        else:
                            facts[("NAM", "has_completed_focus", "NAM_board_" + focus)] = True
                            self.apply(block(decision, "complete_effect"), facts)
                            self.assertEqual(facts[("NAM", "variable", "NAM_board_action_used")], 1)
                            action = block(decision, "remove_effect")
                        if not after:
                            self.apply(action, facts)
                        facts[("NAM", "variable", "NAM_board_company_input")] = company
                        facts[("NAM", "variable", "NAM_board_motion_input")] = motion
                        self.apply(self.effects["NAM_board_adopt_motion"], facts)
                        if after:
                            self.apply(action, facts)
                        self.assertEqual(facts[("NAM", "variable", "NAM_judas_last_op_" + camp)], 2000)
                        self.assertEqual(facts[("NAM", "has_active_mission", "NAM_board_resolution_" + owner)], not after)
                        self.assertEqual(facts[("NAM", "array", "NAM_board_motion")][company], 0 if after else motion)


    def test_two_judases_reports_each_camp_and_reserves_the_choices_for_focuses(self):
        categories = parsed(f"common/decisions/categories/{BASE}_categories.txt")
        category = block(categories, "NAM_two_judases")
        self.assertEqual(scalar(category, "visible_when_empty"), "yes")
        panels = block(parsed("common/scripted_guis/ADISCORD_NAM_scripted_gui.txt"), "scripted_gui")
        panel = block(panels, scalar(category, "scripted_gui"))
        gui = block(parsed("interface/ADISCORD_NAM_basin.gui"), "guiTypes")
        dossier = next(e.value for e in gui if scalar(e.value, "name") == scalar(panel, "window_name"))
        cards = {scalar(e.value, "name"): e.value for e in dossier if e.key == "containerWindowType"}
        self.assertEqual(scalar(block(dossier, "size"), "height"), "164")
        for card in cards.values():
            self.assertEqual(scalar(block(card, "position"), "y"), "14")
        cabinets = block(parsed(f"common/decisions/{BASE}_decisions.txt"), "NAM_two_judases")
        self.assertEqual({e.key for e in cabinets}, {
            "NAM_exile_drill", "NAM_island_recruit_warehouse_guards", "NAM_island_requisition_transports",
            "NAM_judas_weber_meeting", "NAM_judas_karamyshev_meeting",
            "NAM_judas_buy_notes", "NAM_judas_unseat_proxies",
            "NAM_judas_exchange_hiring", "NAM_judas_pay_moderates",
            "NAM_judas_disperse_mourners", "NAM_judas_register_patents",
            "NAM_judas_appoint_masters", "NAM_judas_buy_mortgages",
            "NAM_judas_pay_captains", "NAM_judas_disarm_cutters",
        })
        initial = self.facts()
        self.assertFalse(self.matches(block(category, "visible"), initial))
        for debug in (False, True):
            facts = {**initial, ("NAM", "has_country_flag", "NAM_corp_takeover"): True,
                     ("NAM", "has_country_flag", "NAM_debug_corporate_start"): debug}
            self.assertTrue(self.matches(block(category, "visible"), facts))
        lanes = (
            ("Weber", "NAM_Yaroslav_Weber", "NAM_board_treaty_two_judases", "NAM_board_last_debtor",
             "NAM_island_recruit_warehouse_guards"),
            ("Karamyshev", "NAM_Rostislav_Karamyshev", "NAM_board_escheated_throne", "NAM_board_posthumous_signature",
             "NAM_island_requisition_transports"),
        )
        script = parsed(f"common/scripted_localisation/{BASE}_scripted_loc.txt")
        history = parsed("history/countries/NAM - NamestnikLand.txt")
        for person, character, accord, death, programme in lanes:
            self.assertEqual([e.value for e in history if e.key == "recruit_character"].count(character), 1)
            key = "NAM_judas_" + person.lower()
            camp = key + ("_committees" if person == "Weber" else "_watch")
            card = cards[key + "_card"]
            for widget in (e.value for e in card if e.key in ("instantTextBoxType", "iconType")):
                self.assertEqual(scalar(widget, "pdx_tooltip"), key + "_details")
            for getter, active, closed in (("Summary", "_agenda", "_standing"), ("Block", "_block", "_block_closed")):
                selector = next(e.value for e in script if scalar(e.value, "name") == f"NAMJudas{person}{getter}")
                options = [e.value for e in selector if e.key == "text"]
                for has_camp, killed in product((True, False), repeat=2):
                    facts = {**initial, ("NAM", "has_idea", camp): has_camp, ("NAM", "has_completed_focus", death): killed}
                    selected = next(scalar(row, "localization_key") for row in options if self.matches(
                        next((e.value for e in row if e.key == "trigger"), []), facts))
                    self.assertEqual(selected, key + (active if has_camp and not killed else closed))
            report = next(e.value for e in script if scalar(e.value, "name") == f"NAMIsland{person}Status")
            ruler = block(next(e.value for e in report if e.key == "text"), "trigger")
            self.assertEqual(scalar(block(ruler, "has_country_leader"), "character"), character)
            self.assertEqual(scalar(block(ruler, "has_country_leader"), "ruling_only"), "yes")
            values = [e.value for e in report if e.key == "text"]
            for mandate, expected in ((None, "undecided"), (accord, "outside"), (death, "killed")):
                facts = {**initial, ("NAM", "has_completed_focus", mandate): True}
                selected = next(scalar(row, "localization_key") for row in values if self.matches(
                    next((e.value for e in row if e.key == "trigger"), []), facts))
                self.assertEqual(selected, f"NAM_island_{person.lower()}_{expected}")
                self.assertEqual(self.matches(block(block(cabinets, programme), "visible"), facts), mandate == death)

