    def test_board_card_text_and_icons_fit_the_smallest_seat(self):
        import os
        from PIL import Image

        game = os.environ.get("HOI4_GAME_DIR")
        if not game:
            self.skipTest("Set HOI4_GAME_DIR to measure the board cards with the game's bitmap fonts")

        def asset(relative):
            mod_path = ROOT / relative
            return mod_path if mod_path.is_file() else Path(game) / relative

        gui = block(parsed("interface/ADISCORD_NAM_basin.gui"), "guiTypes")
        window = next(e.value for e in gui if scalar(e.value, "name") == "ADISCORD_NAM_board_window")
        seats = [e.value for e in window if e.key == "instantTextBoxType"
                 and re.fullmatch(r"NAM_board_seat_[1-6]", scalar(e.value, "name"))]
        self.assertEqual(len(seats), 6)
        width = min(int(scalar(seat, "maxWidth")) for seat in seats)
        height = min(int(scalar(seat, "maxHeight")) for seat in seats)
        font_name, = {scalar(seat, "font") for seat in seats}
        font = next(e.value for e in walk(parsed("interface/core.gfx"))
                    if e.key == "bitmapfont" and scalar(e.value, "name") == font_name)
        advances = {}
        line_height = 0
        for sheet in block(font, "fontfiles"):
            path = asset(sheet.value + ".fnt")
            if not path.is_file():
                self.skipTest(f"Installed bitmap font unavailable: {path.name}")
            metrics = path.read_text(encoding="utf-8-sig")
            line_height = max(line_height, int(re.search(r"\blineHeight=(\d+)", metrics)[1]))
            for char, advance in re.findall(r"(?m)^char id=(\d+) .*?xadvance=(-?\d+)", metrics):
                advances[chr(int(char))] = int(advance)

        sprites = {}
        for path in ("interface/ADISCORD_NAM_basin.gfx", "interface/modifiericons_texticons.gfx"):
            for sprite in block(parsed(path), "spriteTypes"):
                if sprite.key == "spriteType":
                    sprites[scalar(sprite.value, "name")] = sprite.value
        dimensions = {}
        icon_token = re.compile(r"£(\w+)(?:\|\d+)?(.?)", re.S)

        def visible_lines(value):
            # The text renderer ends a texticon name at the next character and drops that
            # character, so a line break or full stop written right after an icon is lost.
            text = re.sub(r"§.", "", value.replace(r"\n", "\n"))
            for match in icon_token.finditer(text):
                self.assertEqual(match[2], " ", f"text right after £{match[1]} is swallowed: {value}")
            return icon_token.sub(lambda match: "£" + match[1] + "£", text).split("\n")

        def measure(line):
            parts = line.split("£")
            pixels = sum(advances[char] for text in parts[::2] for char in text)
            tallest = line_height
            for icon in parts[1::2]:
                if icon not in dimensions:
                    sprite = sprites["GFX_" + icon]
                    texture = next(e.value for e in sprite if e.key.lower() == "texturefile")
                    frames = int(next((e.value for e in sprite if e.key.lower() == "noofframes"), 1))
                    with Image.open(asset(texture)) as image:
                        dimensions[icon] = image.width // frames, image.height
                icon_width, icon_height = dimensions[icon]
                pixels += icon_width
                tallest = max(tallest, icon_height)
            return pixels, tallest

        boxes = {scalar(e.value, "name"): e.value for e in window if e.key == "instantTextBoxType"}
        for lang in ("russian", "english"):
            source = read(f"localisation/{lang}/{BASE}_l_{lang}.yml")
            loc = {m[1]: m[2] for line in source.splitlines() if (m := ENTRY.match(line))}

            def fits(key, value, lines=None):
                with self.subTest(lang=lang, box=key, value=value):
                    visible = visible_lines(value)
                    if lines is not None:
                        self.assertEqual(len(visible), lines, value)
                    metrics = [measure(line) for line in visible]
                    self.assertLessEqual(max(w for w, _ in metrics), int(scalar(boxes[key], "maxWidth")))
                    self.assertLessEqual(sum(h for _, h in metrics), int(scalar(boxes[key], "maxHeight")))

            # Every seat shows each company in every stance with three-digit trust and two-digit votes.
            for seat, company in product(range(1, 7), range(1, 7)):
                card = loc[f"NAM_board_company_{company}_card"].replace(f"$NAM_board_short_{company}$", loc[f"NAM_board_short_{company}"])
                card = card.replace(f"[?NAM_board_support^{company}|0]", "100").replace(f"[?NAM_board_votes_{company}|0]", "19")
                for status in ("for", "waiting", "countdown", "boycott"):
                    state = loc[f"NAM_board_rep_{status}"].replace("[?NAM_board_days_to_boycott|0]", "30")
                    display = loc[f"NAM_board_seat_{seat}"].replace(f"[NAMBoardSeat{seat}Card]", card)
                    fits(f"NAM_board_seat_{seat}", display.replace(f"[NAMBoardSeat{seat}Stance]", state), lines=3)
            for seat in range(1, 7):
                display = loc[f"NAM_board_seat_{seat}"].replace(f"[NAMBoardSeat{seat}Card]", loc["NAM_board_seat_empty"])
                fits(f"NAM_board_seat_{seat}", display.replace(f"[NAMBoardSeat{seat}Stance]", loc["NAM_board_rep_none"]))
            owners = [loc[f"NAM_board_short_{i}"] for i in range(1, 7)] + [loc["NAM_board_public_owner"]]
            for asset_name, owner in product(("rail", "yards", "depots"), owners):
                key = "NAM_board_registry_" + asset_name
                fits(key, loc[key].replace(f"[NAMBoardOwner{asset_name.title()}]", owner), lines=2)
            for asset_name, company in (("oil", 1), ("coast", 3), ("labour", 5)):
                key = "NAM_board_registry_" + asset_name
                fits(key, loc[key].replace(f"$NAM_board_short_{company}$", loc[f"NAM_board_short_{company}"]), lines=2)
            for key in ("NAM_board_chartered_caption", "NAM_board_tenders_caption"):
                fits(key, loc[key], lines=1)

            majority = loc["NAM_board_majority_days"].replace("[?NAM_board_held_days|0]", "60")
            votes = re.sub(r"\[\?NAM_board_votes_\w+\|0\]", "29", loc["NAM_board_vote_panel"])
            for state in (majority, loc["NAM_board_majority_absent"]):
                fits("NAM_board_vote_panel", votes.replace("[NAMBoardMajority]", state))
            for index in range(7):
                head = loc[f"NAM_board_head_short_{index}"]
                panel = loc["NAM_board_chair_panel"].replace("[NAMBoardChairShort]", head).replace("[NAMBoardMeetingShort]", head)
                fits("NAM_board_chair_panel", panel.replace("[NAMBoardSessionDays]", "60").replace("[NAMBoardMeetingDays]", "360"))
                forecast = loc["NAM_board_chair_unchanged"].replace("[NAMBoardChairShort]", head)
                risk = re.sub(r"\[\?\w+\|0\]", "45", loc["NAM_board_risk_confidence"])
                fits("NAM_board_council_line", risk.replace("[NAMBoardConfidenceForecast]", forecast))
                if index:
                    head_key = re.search(r"\$(NAM_[A-Z]\w+)\$ \(\$NAM_trait_", loc[f"NAM_board_company_{index}_details"])[1]
                    fits("NAM_board_council_line", risk.replace("[NAMBoardConfidenceForecast]", loc[head_key]))

    def test_board_rank_selects_the_same_company_emblem_votes_minister_and_industrial_rates(self):

        metric_icons = {
            "output": "factory_output_texticon", "construction": "construction_speed_texticon",
            "growth": "efficiency_growth_texticon", "naval": "dockyard_output_texticon",
            "dockyards": "construction_speed_dockyard_texticon", "ceiling": "prod_eff_cap",
            "goods": "consumer_goods_texticon",
        }
        gui = block(parsed("interface/ADISCORD_NAM_basin.gui"), "guiTypes")
        window = next(e.value for e in gui if scalar(e.value, "name") == "ADISCORD_NAM_board_window")
        icons = {scalar(e.value, "name"): e.value for e in window if e.key == "iconType"}
        scripted = block(parsed("common/scripted_guis/ADISCORD_NAM_scripted_gui.txt"), "scripted_gui")
        properties = block(block(scripted, "ADISCORD_NAM_board_panel"), "properties")
        for rank in range(1, 7):
            name = f"NAM_board_mark_{rank}"
            self.assertEqual(scalar(icons[name], "spriteType"), "GFX_NAM_board_company_marks")
            self.assertEqual(scalar(icons[name], "pdx_tooltip"), f"NAM_board_seat_{rank}_tt")
            self.assertEqual(scalar(block(properties, name), "frame"), f"NAM_board_rank_{rank}")
        texts = {scalar(e.value, "name"): e.value for e in parsed(
            f"common/scripted_localisation/{BASE}_scripted_loc.txt") if e.key == "defined_text"}
        for rank, kind in product(range(1, 7), ("Card", "Details")):
            branches = [e.value for e in texts[f"NAMBoardSeat{rank}{kind}"] if e.key == "text"]
            choices = {scalar(block(block(e, "trigger"), "check_variable"), f"NAM_board_rank_{rank}"):
                       scalar(e, "localization_key") for e in branches[:-1]}
            self.assertEqual(choices, {str(i): f"NAM_board_company_{i}_{kind.lower()}" for i in range(1, 7)})
            self.assertEqual(scalar(branches[-1], "localization_key"), "NAM_board_seat_empty")
        # The stance strip holds 1 for, 2 waiting, 3 countdown, 4 boycott; the word and the
        # tooltip line of a seat read the same frame variable as its icon.
        for rank, (kind, prefix) in product(range(1, 7), (("Stance", "NAM_board_rep"), ("Position", "NAM_board_position"))):
            statuses = [e.value for e in texts[f"NAMBoardSeat{rank}{kind}"] if e.key == "text"]
            self.assertEqual([scalar(s, "localization_key") for s in statuses],
                             [f"{prefix}_{state}" for state in ("for", "boycott", "countdown", "waiting")] + ["NAM_board_rep_none"])
            frames = [[(e.key, e.value) for e in block(block(status, "trigger"), "check_variable")] for status in statuses[:4]]
            self.assertEqual(frames, [[(f"NAM_board_stance_frame_{rank}", value)] for value in ("1", "4", "3", "2")])
            countdown = block(statuses[2], "trigger")
            timer = "NAM_board_days_to_boycott"
            for operation, source in (("set_temp_variable", f"NAM_board_objection_days^NAM_board_rank_{rank}"),
                                      ("subtract_from_temp_variable", "global.num_days")):
                calculation = block(countdown, operation)
                self.assertEqual((scalar(calculation, "var"), scalar(calculation, "value")), (timer, source))
            self.assertNotIn("trigger", [e.key for e in statuses[4]])
        for lang in ("russian", "english"):
            source = read(f"localisation/{lang}/{BASE}_l_{lang}.yml")
            loc = {m[1]: m[2] for line in source.splitlines() if (m := ENTRY.match(line))}
            for key in ("NAM_board_rep_countdown", "NAM_board_position_countdown"):
                self.assertIn("[?NAM_board_days_to_boycott|0]", loc[key])
            self.assertEqual(loc["NAM_board_rep_none"], "")
            for rank in range(1, 7):
                self.assertEqual(loc[f"NAM_board_seat_{rank}"], f"[NAMBoardSeat{rank}Card] \\n[NAMBoardSeat{rank}Stance]")
                self.assertEqual(loc[f"NAM_board_seat_{rank}_tt"], f"[NAMBoardSeat{rank}Details][NAMBoardSeat{rank}Position]")
            self.assertEqual(loc["NAM_board_chair_caption"], "§YПервое место§!" if lang == "russian" else "§YFirst place§!")
            self.assertEqual(loc["NAM_board_technocrats_title"], "Совет правлений" if lang == "russian" else "Council of Boards")
            heads = ("NAM_Aristarkh_Vyazemtsev", "NAM_Taisiya_Valts", "NAM_Saveliy_Kruze", "NAM_Rodion_Kalyonov", "NAM_Nazar_Guryev", "NAM_Lidiya_Velyaminova")
            traits = ("NAM_trait_oil_patriarch", "NAM_trait_steel_trust_director", "NAM_trait_freight_king", "NAM_trait_order_before_profit", "NAM_trait_exchange_steward", "NAM_trait_bill_holder")
            motions = ("loren", "ferrant", "navis", "arktur", "smenkom", "reidbank")
            for i in range(1, 7):
                card = loc[f"NAM_board_company_{i}_card"]
                details = loc[f"NAM_board_company_{i}_details"]
                head, trait = heads[i - 1], traits[i - 1]
                for key in (head, trait, trait + "_desc", "NAM_board_resolution_" + motions[i - 1]):
                    self.assertIn(f"${key}$", details)
                    self.assertIn(key, loc)
                self.assertRegex(loc[trait + "_desc"], r"[+-]\d.*? \$MODIFIER")
                for metric in ("support", "forecast", "rest", "seat_count"):
                    self.assertIn(f"[?NAM_board_{metric}^{i}|0]", details)
                self.assertIn(f"[NAMBoardAgenda{i}]", details)
                self.assertIn(f"£NAM_board_mark_texticon|{i} ", details)
                for value in (card, details):
                    self.assertIn(f"[?NAM_board_votes_{i}|0]", value)
                    self.assertIn(f"[?NAM_board_support^{i}|0]", value)
                self.assertNotIn("NAMBoardRepresentative", details)
                self.assertNotIn("NAM_board_rate_", card)
                self.assertEqual(details.count(f"$NAM_board_profile_{i}$"), 1)
                self.assertNotIn("NAM_board_profile_", card)
                self.assertEqual(details.count("[?NAM_board_rate_"), 2)
                for field, (metric, bonus) in zip(("a", "b"), BOARD_PROFILES[i - 1]):
                    colour = "+" if bonus > 0 else "-"
                    rate = f"[?NAM_board_rate_{field}_{i}|={colour}1]%"
                    self.assertEqual(details.count(f"{rate} £{metric_icons[metric]}"), 1)
                    self.assertNotIn("£" + metric_icons[metric], card)
                self.assertIn(f"[?NAM_board_sectors_{i}|0]", details)
                self.assertIn(f"[?NAM_board_districts_{i}|0]", details)
                profile = loc[f"NAM_board_profile_{i}"]
                for minister in BOARD_MINISTERS[i - 1]:
                    self.assertIn(f"${minister}$", details)
                pairs = re.findall(r"§G([+-][\d.,]+)%§! / §R([+-][\d.,]+)%§! (£\w+)", profile)
                self.assertEqual(len(pairs), 2, (lang, i))
                for (appointed, boycott, icon), (metric, bonus) in zip(pairs, BOARD_PROFILES[i - 1]):
                    self.assertEqual(icon, "£" + metric_icons[metric])
                    self.assertEqual(float(appointed.replace(",", ".")), bonus)
                    self.assertEqual(float(boycott.replace(",", ".")), -bonus / 2)
            self.assertIn("$NAM_board_labor_nominee$", loc["NAM_board_company_5_details"])
            self.assertIn("$NAM_board_bank_nominee$", loc["NAM_board_company_6_details"])
            for number, asset in ((28, "Rail"), (29, "Yards"), (30, "Depots")):
                self.assertIn(f"[NAMBoardOwner{asset}]", loc[f"ADISCORD_nam_story.{number}.d"])
        for asset, buyers in (("Rail", (2, 5)), ("Yards", (3, 4)), ("Depots", (1, 6))):
            branches = [e.value for e in texts["NAMBoardOwner" + asset] if e.key == "text"]
            self.assertEqual([scalar(e, "localization_key") for e in branches],
                             [*(f"NAM_board_short_{i}" for i in buyers), "NAM_board_public_owner"])

